INSERT INTO restaurante VALUES
                            (1, '/src/assets/restaurante1.jpg', 'D.O.M.', 'São Paulo, SP', 4.6, 'Comandado pelo chef Alex Atala, o D.O.M. é um dos restaurantes mais reconhecidos do Brasil. A casa combina ingredientes brasileiros com técnicas contemporâneas e uma abordagem autoral. Localizado nos Jardins, tornou-se referência internacional na gastronomia brasileira.'),
                            (2, '/src/assets/restaurante2.jpg', 'Evvai', 'São Paulo, SP', 4.7, 'Comandado pelo chef Luiz Filipe Souza, o Evvai explora a relação entre as cozinhas italiana e brasileira. O restaurante trabalha com ingredientes brasileiros em pratos contemporâneos e criativos. Em 2026, conquistou três estrelas Michelin, a classificação máxima do guia.'),
                            (3, '/src/assets/restaurante3.jpg', 'Tuju', 'São Paulo, SP', 4.7, 'O Tuju, comandado pelo chef Ivan Ralston, valoriza ingredientes brasileiros e a sazonalidade. Seu menu combina técnicas contemporâneas com produtos de diferentes regiões do país. Em 2026, recebeu três estrelas Michelin e se tornou um dos grandes destaques gastronômicos do Brasil.'),
                            (4, '/src/assets/restaurante4.jpg', 'Maní', 'São Paulo, SP', 4.6, 'Fundado pela chef Helena Rizzo, o Maní combina referências brasileiras com influências internacionais. A cozinha utiliza ingredientes nacionais em pratos criativos e contemporâneos. O restaurante está localizado no bairro de Pinheiros e possui uma estrela Michelin.'),
                            (5, '/src/assets/restaurante5.jpg', 'A Casa do Porco', 'São Paulo, SP', 4.6, 'Criado pelos chefs Janaína e Jefferson Rueda, o restaurante tem o porco como um de seus principais ingredientes. A casa apresenta uma cozinha brasileira contemporânea com forte valorização de produtos nacionais. Localizada no centro de São Paulo, possui reconhecimento internacional e Estrela Verde Michelin.'),
                            (6, '/src/assets/restaurante6.jpg', 'Mocotó', 'São Paulo, SP', 4.7, 'Fundado por Rodrigo Oliveira, o Mocotó é conhecido por valorizar a culinária nordestina. O restaurante apresenta pratos tradicionais reinterpretados com ingredientes brasileiros e técnicas contemporâneas. Localizado na Vila Medeiros, tornou-se uma referência da gastronomia popular paulistana.'),
                            (7, '/src/assets/restaurante7.jpg', 'Lasai', 'Rio de Janeiro, RJ', 4.7, 'Comandado pelo chef Rafa Costa e Silva, o Lasai apresenta uma cozinha contemporânea baseada em ingredientes sazonais. Muitos vegetais utilizados no restaurante são cultivados em hortas próprias. Localizado em Humaitá, o restaurante possui duas estrelas Michelin.'),
                            (8, '/src/assets/restaurante8.jpg', 'Oteque', 'Rio de Janeiro, RJ', 4.7, 'Comandado pelo chef Alberto Landgraf, o Oteque apresenta uma cozinha contemporânea com forte influência brasileira. O restaurante trabalha principalmente com ingredientes do mar e produtos sazonais. Localizado em Botafogo, tornou-se um dos restaurantes de destaque da gastronomia carioca.'),
                            (9, '/src/assets/restaurante9.jpg', 'Oro', 'Rio de Janeiro, RJ', 4.6, 'Comandado pelo chef Felipe Bronze, o Oro apresenta uma cozinha brasileira contemporânea e autoral. A experiência é baseada em menus degustação que valorizam técnicas modernas e ingredientes nacionais. Localizado no Leblon, o restaurante possui duas estrelas Michelin.'),
                            (10, '/src/assets/restaurante10.jpg', 'Jun Sakamoto', 'São Paulo, SP', 4.6, 'O restaurante Jun Sakamoto é conhecido por sua culinária japonesa sofisticada e minimalista. O chef Jun Sakamoto valoriza ingredientes de alta qualidade e técnicas tradicionais japonesas. Localizado em Pinheiros, o restaurante possui uma estrela Michelin.'),
                            (11, '/src/assets/restaurante11.jpg', 'Kinoshita', 'São Paulo, SP', 4.5, 'O Kinoshita apresenta uma cozinha japonesa contemporânea com influência brasileira. A casa valoriza ingredientes frescos e técnicas tradicionais combinadas a uma abordagem moderna. Localizado na Vila Nova Conceição, possui uma estrela Michelin.'),
                            (12, '/src/assets/restaurante12.jpg', 'Fame Osteria', 'São Paulo, SP', 4.6, 'A Fame Osteria apresenta uma cozinha italiana contemporânea com pratos inspirados em diferentes regiões da Itália. O restaurante trabalha com massas, ingredientes sazonais e técnicas tradicionais. A casa possui uma estrela Michelin e está localizada em São Paulo.'),
                            (13, '/src/assets/restaurante13.jpg', 'Picchi', 'São Paulo, SP', 4.5, 'Comandado pelo chef Pier Paolo Picchi, o restaurante apresenta uma cozinha italiana contemporânea. O menu combina receitas tradicionais italianas com ingredientes brasileiros e técnicas modernas. Localizado nos Jardins, o restaurante possui uma estrela Michelin.'),
                            (14, '/src/assets/restaurante14.jpg', 'Madame Olympe', 'Rio de Janeiro, RJ', 4.7, 'Comandado por Claude Troisgros e Jéssica Trindade, o restaurante apresenta uma cozinha francesa contemporânea. A proposta combina técnicas francesas com ingredientes brasileiros e algumas influências japonesas. Localizado no Leblon, recebeu sua primeira estrela Michelin em 2026.'),
                            (15, '/src/assets/restaurante15.jpg', 'MEE', 'Rio de Janeiro, RJ', 4.6, 'Localizado no Copacabana Palace, o MEE apresenta uma experiência gastronômica inspirada na culinária asiática. O menu reúne influências de diferentes países do continente e ingredientes selecionados. O restaurante possui uma estrela Michelin e está localizado em Copacabana.'),
                            (16, '/src/assets/restaurante16.jpg', 'Fasano', 'São Paulo, SP', 4.6, 'O Fasano é um dos restaurantes italianos mais tradicionais e sofisticados de São Paulo. A casa faz parte do histórico grupo Fasano e é conhecida por sua cozinha italiana clássica. Localizado nos Jardins, tornou-se referência na gastronomia de alto padrão da cidade.'),
                            (17, '/src/assets/restaurante17.jpg', 'Tangará Jean-Georges', 'São Paulo, SP', 4.6, 'Localizado no Palácio Tangará, o restaurante é comandado pelo chef Jean-Georges Vongerichten. A cozinha combina técnicas contemporâneas com influências internacionais e ingredientes selecionados. O ambiente sofisticado complementa a experiência gastronômica no Morumbi.'),
                            (18, '/src/assets/restaurante18.jpg', 'Komah', 'São Paulo, SP', 4.6, 'O Komah apresenta uma cozinha coreana contemporânea com forte identidade autoral. O restaurante valoriza receitas tradicionais da Coreia adaptadas a uma experiência gastronômica moderna. Localizado na Barra Funda, tornou-se conhecido entre os restaurantes asiáticos de São Paulo.'),
                            (19, '/src/assets/restaurante19.jpg', 'Corrutela', 'São Paulo, SP', 4.6, 'A Corrutela trabalha com uma cozinha baseada em ingredientes sazonais e práticas sustentáveis. O restaurante procura valorizar produtores locais e reduzir o desperdício durante sua operação. Localizado na Vila Madalena, possui uma Estrela Verde Michelin.'),
                            (20, '/src/assets/restaurante20.jpg', 'Cepa', 'São Paulo, SP', 4.6, 'A Cepa apresenta uma cozinha contemporânea focada em ingredientes brasileiros e produtos sazonais. O restaurante busca valorizar pequenos produtores e técnicas que preservam os sabores dos ingredientes. Localizada no Tatuapé, a casa integra a seleção do Guia Michelin.'),
                            (21, '/src/assets/restaurante21.jpg', 'Banzeiro', 'São Paulo, SP', 4.5, 'O Banzeiro é conhecido por apresentar sabores e ingredientes da culinária amazônica. O restaurante valoriza produtos típicos da região Norte, levando ingredientes brasileiros para uma cozinha contemporânea. A unidade paulistana está localizada no Itaim Bibi.'),
                            (22, '/src/assets/restaurante22.jpg', 'Manioca', 'São Paulo, SP', 4.5, 'O Manioca apresenta uma cozinha brasileira contemporânea com ingredientes e referências de diferentes regiões do país. A casa pertence ao grupo Maní, criado pela chef Helena Rizzo e pelo restaurateur Daniel Redondo. Localizado no Shopping Iguatemi, combina gastronomia e ambiente sofisticado.'),
                            (23, '/src/assets/restaurante23.jpg', 'Kotori', 'São Paulo, SP', 4.6, 'O Kotori é especializado em culinária japonesa contemporânea e destaca preparos feitos na brasa. O restaurante combina técnicas japonesas com ingredientes e influências brasileiras. Localizado em São Paulo, integra a seleção de restaurantes do Guia Michelin.'),
                            (24, '/src/assets/restaurante24.jpg', 'Zena Cucina', 'São Paulo, SP', 4.6, 'A Zena Cucina apresenta uma interpretação contemporânea da cozinha italiana. O restaurante valoriza massas, ingredientes frescos e receitas inspiradas na tradição italiana. Localizado nos Jardins, tornou-se uma opção conhecida para gastronomia italiana na cidade.'),
                            (25, '/src/assets/restaurante25.jpg', 'Casa Santo Antônio', 'São Paulo, SP', 4.6, 'A Casa Santo Antônio apresenta uma cozinha italiana com influência contemporânea. O restaurante é conhecido por massas artesanais, carnes e pratos inspirados em receitas tradicionais. Localizado no Alto da Boa Vista, oferece uma experiência gastronômica em ambiente acolhedor.'),
                            (26, '/src/assets/restaurante26.jpg', 'Ryo Gastronomia', 'São Paulo, SP', 4.7, 'O Ryo Gastronomia apresenta uma experiência japonesa baseada em ingredientes selecionados e técnicas tradicionais. O restaurante trabalha principalmente com menus degustação e preparos delicados. Localizado em São Paulo, é reconhecido pelo Guia Michelin por sua cozinha japonesa.'),
                            (27, '/src/assets/restaurante27.jpg', 'Kan Suke', 'São Paulo, SP', 4.6, 'O Kan Suke é um restaurante japonês conhecido por sua proposta tradicional e ambiente intimista. A casa valoriza ingredientes frescos e técnicas clássicas da culinária japonesa. Localizado em São Paulo, possui reconhecimento na seleção do Guia Michelin.'),
                            (28, '/src/assets/restaurante28.jpg', 'Capim Santo', 'São Paulo, SP', 4.5, 'O Capim Santo valoriza ingredientes brasileiros e uma cozinha inspirada na diversidade gastronômica do país. A chef Morena Leite é conhecida por trabalhar sabores brasileiros com técnicas contemporâneas. O restaurante possui uma longa trajetória e está localizado em São Paulo.'),
                            (29, '/src/assets/restaurante29.jpg', 'Bar da Dona Onça', 'São Paulo, SP', 4.5, 'Comandado pela chef Janaína Rueda, o Bar da Dona Onça valoriza receitas brasileiras e sabores populares. O cardápio combina pratos tradicionais com interpretações contemporâneas e ingredientes nacionais. Localizado no centro de São Paulo, o restaurante integra a seleção recomendada pelo Guia Michelin.'),
                            (30, '/src/assets/restaurante30.jpg', 'Jiquitaia', 'São Paulo, SP', 4.5, 'O Jiquitaia apresenta uma cozinha brasileira contemporânea inspirada em diferentes regiões do país. O restaurante procura trabalhar ingredientes nacionais em pratos criativos e acessíveis. Localizado em São Paulo, recebeu a distinção Bib Gourmand do Guia Michelin.');